const conflicted = [
  '<<<<<<< HEAD',
  'Port: 8080',
  '=======',
  'Port: 9090',
  '>>>>>>> feature-port'
].join('\n');

function resolveConflict(text, strategy) {
  const lines = text.split('\n');
  const start = lines.findIndex(l => l.startsWith('<<<<<<<'));
  const mid = lines.findIndex(l => l.startsWith('======='));
  const end = lines.findIndex(l => l.startsWith('>>>>>>>'));
  const ours = lines.slice(start + 1, mid).join('\n');
  const theirs = lines.slice(mid + 1, end).join('\n');
  if (strategy === 'ours') return ours;
  if (strategy === 'theirs') return theirs;
  return ours + '\n' + theirs;
}

console.log('OURS:', resolveConflict(conflicted, 'ours'));
console.log('THEIRS:', resolveConflict(conflicted, 'theirs'));
console.log('BOTH:', resolveConflict(conflicted, 'both'));

import fnmatch

rules = [
    '# Ignore all text files',
    '*.txt',
    '!examples/*_input.txt',
    '/target/'
]

def is_ignored(path, rules):
    ignored = False
    for raw in rules:
        rule = raw.strip()
        if not rule or rule.startswith('#'):
            continue
        negated = rule.startswith('!')
        pattern = rule[1:] if negated else rule
        matched = False
        if pattern.startswith('/') and pattern.endswith('/'):
            matched = path.startswith(pattern.strip('/') + '/')
        else:
            matched = fnmatch.fnmatch(path, pattern) or fnmatch.fnmatch(path.split('/')[-1], pattern)
        if matched:
            ignored = not negated
    return ignored

files = ['notes.txt', 'examples/lab1_input.txt', 'target/App.class', 'src/Main.java']
for f in files:
    print(f'{f}: {"IGNORED" if is_ignored(f, rules) else "TRACKED"}')

