flowchart TD
  Push["git push"] -->|"! [rejected] (fetch first)"| Pull["git pull (with pull.rebase = true)"]
  Pull --> Conflict{"Merge conflict?"}
  Conflict -->|"No"| PushOK["git push (succeeds)"]
  Conflict -->|"Yes"| Edit["Edit file & remove <<< === >>> markers"]
  Edit --> Add["git add resolved-file"]
  Add --> Cont["git rebase --continue"]
  Cont --> Conflict

  classDef err fill:#ffe4e6,stroke:#e11d48,stroke-width:1.5px;
  classDef act fill:#f0f9ff,stroke:#0284c7,stroke-width:1.5px;
  classDef ok fill:#ecfdf5,stroke:#059669,stroke-width:2px;

  class Push err;
  class Pull,Edit,Add,Cont act;
  class PushOK ok;
